// hitung total belanja dengan diskon
import { format } from "./uang.js";

export function total(keranjang, diskon = 0) {
  const jumlah = keranjang.reduce((a, b) => a + b.harga * b.qty, 0);
  if (diskon > 0) {
    return format(jumlah * (1 - diskon / 100));
  }
  return format(jumlah);
}

console.log(total([{ harga: 25000, qty: 2 }], 10));
